const darkSurfaceClasses = new Set([
  "hero",
  "dark-section",
  "industries-section",
  "cta-panel",
  "about-command-panel",
  "contact-form",
  "site-footer",
  "services-hero",
  "sticky-services",
  "services-benefits",
  "featured-service-case",
  "technology-system",
  "services-final-cta",
]);

const darkSurfaceUtilities =
  "[--card:#172033] [--muted:#cbd5e1] [--line:rgba(255,255,255,0.08)] text-white";

export function tw(...inputs: Array<string | false | null | undefined>) {
  const tokens = inputs.filter(Boolean).join(" ").trim().split(/\s+/).filter(Boolean);
  return tokens
    .flatMap((token) => [
      token,
      componentStyles[token as keyof typeof componentStyles] ?? "",
      darkSurfaceClasses.has(token) ? darkSurfaceUtilities : "",
    ])
    .filter(Boolean)
    .join(" ");
}
